//! The contracts services speak to each other.
//!
//! Each service also serves the same data over HTTP where a browser needs it; the protobuf
//! here is what the instance's own processes use, so a field only appears if some process
//! reads it.

pub mod telemetry {
    // Generated by tonic from the contract: it is not ours to restyle, and the pedantic
    // lints it trips say nothing about how this instance behaves.
    #![allow(clippy::pedantic, clippy::result_large_err)]

    tonic::include_proto!("nodus.telemetry");
}

pub mod control {
    #![allow(clippy::pedantic, clippy::result_large_err)]

    tonic::include_proto!("nodus.control");
}
